use kimo_core::color::lut::Lut;
fn cube()->String{let mut s="LUT_3D_SIZE 2\nDOMAIN_MIN -1 -1 -1\nDOMAIN_MAX 2 2 2\n".to_string();for b in [-1,2]{for g in [-1,2]{for r in [-1,2]{s+=&format!("{r} {g} {b}\n")}}}s}
#[test]fn domain_identity_all_tetrahedra(){let l=Lut::parse(&cube()).unwrap();for i in 0..1000{let c=[(i%17) as f32/16.,(i%31) as f32/30.,(i%43) as f32/42.];let o=l.sample(c);for j in 0..3{assert!((o[j]-c[j]).abs()<3e-7)}}}
#[test]fn exact_vertices(){let l=Lut::parse(&cube()).unwrap();assert_eq!(l.sample([-1.;3]),[-1.;3]);assert_eq!(l.sample([2.;3]),[2.;3]);}
#[test]fn hostile_cube(){for x in ["LUT_3D_SIZE 0","LUT_3D_SIZE 1\n0 0 0", "LUT_3D_SIZE 999999999999", "LUT_3D_SIZE 2\nNaN 0 0", "LUT_3D_SIZE 2\ninf 0 0", "LUT_3D_SIZE 2\nDOMAIN_MIN 1 1 1\nDOMAIN_MAX 0 0 0", "LUT_3D_SIZE 2\nLUT_3D_SIZE 2"]{assert!(Lut::parse(x).is_err())}}

#[test]fn duplicate_and_late_domain_rejected(){let c=cube();assert!(Lut::parse(&c.replace("DOMAIN_MIN -1 -1 -1","DOMAIN_MIN -1 -1 -1\nDOMAIN_MIN 0 0 0")).is_err());assert!(Lut::parse(&(c+"DOMAIN_MAX 3 3 3\n")).is_err());}
#[test]fn lut_frame_preflight_before_file_access(){use kimo_core::{effects::{Frame,Params},color::lut::apply};let mut f=Frame{w:2,h:1,d:vec![0.;4]};let mut strings=std::collections::BTreeMap::new();strings.insert("path".into(),"/tmp/nonexistent-kimo-lut".into());assert!(apply(&Params::new(),&strings,&mut f,0.).err().unwrap().contains("frame shape"));}
#[test]fn extreme_finite_lut_mix_remains_finite(){use kimo_core::{effects::{Frame,Params},keyframe::Prop,color::lut::apply};let path=std::env::temp_dir().join(format!("kimo-lut-extreme-{}.cube",std::process::id()));std::fs::write(&path,cube()).unwrap();let mut strings=std::collections::BTreeMap::new();strings.insert("path".into(),path.to_string_lossy().into_owned());for amount in [0.,0.5,1.]{let mut p=Params::new();p.insert("intensity".into(),Prop::new(amount));let mut f=Frame{w:1,h:1,d:vec![-f32::MAX,f32::MAX,f32::MAX,1.]};apply(&p,&strings,&mut f,0.).unwrap();assert!(f.d.iter().all(|v|v.is_finite()));if amount==0.{assert_eq!(f.d[0],-f32::MAX);}}std::fs::remove_file(path).unwrap();}

#[test]fn oversized_token_row_is_rejected(){let row="0 ".repeat(200000);let text=format!("LUT_3D_SIZE 2\n{row}\n");assert!(Lut::parse(&text).is_err());let text=cube().replace("LUT_3D_SIZE 2","LUT_3D_SIZE 2 extra ignored?");assert!(Lut::parse(&text).is_err());}
